import yesman.epicfight.skill.Skill;
import yesman.epicfight.world.item.EpicFightItems;
import yesman.epicfight.world.item.SkillBookItem;

public class EpicFightItemProperties {
    public static void registerItemProperties() {
        ItemProperties.register((Item)((Item)EpicFightItems.SKILLBOOK.get()), (ResourceLocation)EpicFightMod.identifier("skill"), (itemstack, level, entity, i) -> {
            Skill skill = SkillBookItem.getContainSkill(itemstack);
